INSERT INTO "users"("id","username","password_hash","display_name","email","title","role","is_active","mfa_secret_enc","mfa_enabled","failed_attempts","locked_until","must_change_password","password_changed_at","last_login_at","hourly_cost","requires_cosign","supervisor_id","oidc_subject","access_status","access_note","requested_at","created_at","updated_at","idp_seen_at","scim_external_id","default_fund_id","totp_last_step","default_site_id") VALUES('b20d0b83-219a-4e3f-80da-20d104e6550c','fxnav2','scrypt$32768$8$1$ldxTEmYHWrHbTh/F0s7dYA==$Ip5iFvkuuCxPHMPmApULjsrinkeOKftbI8aBTjAG3NKBok3h7gQVbpUf81TGf+3TOCSst6Rg8QiUhnn61Vmhng==','Fixture navigator',NULL,NULL,'navigator',1,NULL,0,0,NULL,0,'2026-10-01T04:54:15.414Z',NULL,NULL,0,NULL,NULL,'active',NULL,NULL,'2026-10-01T04:54:15.414Z','2026-10-01T04:54:15.414Z',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "users"("id","username","password_hash","display_name","email","title","role","is_active","mfa_secret_enc","mfa_enabled","failed_attempts","locked_until","must_change_password","password_changed_at","last_login_at","hourly_cost","requires_cosign","supervisor_id","oidc_subject","access_status","access_note","requested_at","created_at","updated_at","idp_seen_at","scim_external_id","default_fund_id","totp_last_step","default_site_id") VALUES('dfa9d588-5114-4c87-a483-eeef076c2381','fxclin','scrypt$32768$8$1$ZyTeGXkKEiatRl2Z5ruVtA==$HgMJo3GO8+N48R4y1o/G58flybjv20FDSCIHCdGo2PFsqulNx6NKI7lzg0eOOK1IxQc2joSqCgH2hDDALfDxQQ==','Fixture clinician',NULL,NULL,'clinician',1,NULL,0,0,NULL,0,'2026-10-01T04:54:15.501Z',NULL,NULL,0,NULL,NULL,'active',NULL,NULL,'2026-10-01T04:54:15.501Z','2026-10-01T04:54:15.501Z',NULL,NULL,NULL,NULL,NULL);
INSERT INTO "users"("id","username","password_hash","display_name","email","title","role","is_active","mfa_secret_enc","mfa_enabled","failed_attempts","locked_until","must_change_password","password_changed_at","last_login_at","hourly_cost","requires_cosign","supervisor_id","oidc_subject","access_status","access_note","requested_at","created_at","updated_at","idp_seen_at","scim_external_id","default_fund_id","totp_last_step","default_site_id") VALUES('abe287a1-4688-46fc-a02f-26dfc06086d0','fxsup','scrypt$32768$8$1$6mrehlRnEIeNHB265kgQDg==$J0kX7kRvDLbfwof9JrHxl06xUa4PnQtkyqN6dwnUGJJnrIqh5qFrCDx7PEDCJpw8zBVdALedMrtGbTS74mGy+Q==','Fixture supervisor',NULL,NULL,'supervisor',1,NULL,0,0,NULL,0,'2026-10-01T04:54:15.586Z',NULL,NULL,0,NULL,NULL,'active',NULL,NULL,'2026-10-01T04:54:15.586Z','2026-10-01T04:54:15.586Z',NULL,NULL,NULL,NULL,NULL);
CREATE TABLE user_permission_overrides (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  permission TEXT NOT NULL,
  mode TEXT NOT NULL CHECK (mode IN ('grant','deny')),
  reason TEXT NOT NULL,
  granted_by TEXT REFERENCES users(id),
  granted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (user_id, permission)
);
INSERT INTO "user_permission_overrides"("user_id","permission","mode","reason","granted_by","granted_at") VALUES('5bb9a771-70ec-4572-b54a-c67774a99537','reports:funder','grant','Fixture: covers the funder report','3c33f58c-aa72-48ef-b4b7-0cfa790798e0','2026-10-01T04:54:16.302Z');
CREATE TABLE devices (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  label TEXT,
  first_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_seen_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_ip TEXT,
  sync_count INTEGER NOT NULL DEFAULT 0,
  wipe_requested_at TEXT,
  revoked_at TEXT,
  -- What this device's sync carries (1.21.0, server/field-scope.js; migration 62): 'full', everything its user may
  -- read, or 'field', only what a field worker needs (their own recent caseload's minimal record, their outreach
  -- contacts, supplies, their own to-dos). Set by an administrator, or narrowed to 'field' by its user when enrolling.
  sync_scope TEXT NOT NULL DEFAULT 'full' CHECK (sync_scope IN ('full','field')),
  scope_changed_at TEXT,
  -- When the office first answered this device's pull under the field scope: from then on its pushes are held to
  -- that scope and its field-shaped rows (blanked columns) never overwrite the office's values. NULL while a change
  -- to 'field' has not reached the device yet, and again once a full-scope pull has completed after it.
  field_applied_at TEXT,
  -- Who last decided sync_scope (1.22.0; migration 64): 'default' (first seen, under field_device_default),
  -- 'enrolment' (its user narrowed it), 'account' (the office narrowed it because its user's account is held to the
  -- field scope, field_accounts), 'admin'. Only 'full' set by 'admin' keeps a device whole for an account held to
  -- the field scope; it is cleared when the device signs in as someone else. NULL: decided before 1.22.0.
  scope_set_by TEXT CHECK (scope_set_by IN ('default','enrolment','account','admin'))
);
CREATE TABLE field_accounts (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  bound_at TEXT NOT NULL,
  bound_via TEXT NOT NULL CHECK (bound_via IN ('default','enrolment','account','admin','device','migration'))
);
CREATE TABLE sessions (
  id TEXT PRIMARY KEY,               -- sha256 of the bearer token
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  mfa_pending INTEGER NOT NULL DEFAULT 0,
  ip TEXT,
  user_agent TEXT,
  revoked_at TEXT,
  -- How this session's second factor was satisfied: NULL (none or SUDS's own TOTP) or 'idp' — the identity
  -- provider asserted multi-factor sign-in (amr/acr) and the administrator chose to trust it (server/routes/oidc.js).
  mfa_source TEXT,
  -- When this session last proved who is using it: the sign-in (password, and the second factor when there is
  -- one), or the password or code given again to sign a note. A signature within sign_reauth_minutes of it
  -- needs only the signer's confirmation (server/routes/notes.js verifyIdentity).
  reauth_at TEXT,
  -- How reauth_at was last proved: 'password', 'totp', 'passkey' (a fingerprint or the device's screen lock,
  -- docs/FINGERPRINT.md) or 'sso'. "Require fingerprint or authenticator for signing" counts only a recent
  -- 'passkey' or 'totp' towards the quick-signing window (migration 58).
  reauth_method TEXT,
  -- The passkey that signed this session in (or finished its second step), when one did: removing that passkey
  -- ends the session (server/passkeys.js remove; migration 58).
  passkey_id TEXT,
  -- 1 for a device's sync sign-in (X-Sync-Client): a device signs in with the password and, with two-step verification
  -- on, the authenticator code; it cannot give a fingerprint, so a passkey does not count as its second factor
  -- (server/auth.js login and requireAuth; docs/FINGERPRINT.md; migration 59).
  sync_client INTEGER NOT NULL DEFAULT 0,
  -- The device (devices.id) a sync sign-in was made from, bound when the session was created (1.21.0, migration 62):
  -- a field device's scope is looked up from it on every pull and push, never taken from a header the device sends.
  device_id TEXT
);
CREATE TABLE passkeys (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  credential_id TEXT NOT NULL UNIQUE,  -- base64url, as the authenticator gave it
  public_key TEXT NOT NULL,            -- SPKI DER, base64
  alg INTEGER NOT NULL,                -- COSE algorithm: -7 ES256, -8 EdDSA, -257 RS256
  sign_count INTEGER NOT NULL DEFAULT 0,
  transports TEXT,                     -- JSON array, as reported
  aaguid TEXT,                         -- the authenticator model, as reported (attestation 'none': unverified)
  backup_eligible INTEGER NOT NULL DEFAULT 0,
  backed_up INTEGER NOT NULL DEFAULT 0,
  rp_id TEXT NOT NULL,                 -- the host it was made for; an assertion must be for the same one
  name TEXT NOT NULL,                  -- "Maria's iPhone": its owner's name for it
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_used_at TEXT,
  -- Set when the signature counter went backwards (a possible copy of the credential): refused from then on,
  -- until the owner or an administrator removes it.
  flagged_at TEXT,
  flag_reason TEXT,
  -- The attestation verified at enrolment under the authenticator allow-list (docs/FINGERPRINT.md, "Authenticator
  -- allow-list"): JSON { verified, fmt, type, aaguid, mds_no, verified_at }. NULL for a passkey added while the list
  -- was off (attestation 'none': its AAGUID is only what the device said), which the list, once on, does not accept.
  -- The attestation certificate itself is not kept (migration 63).
  attestation TEXT,
  -- The authenticator allow-list's grace period (released in 1.22.0, migration 66): when an administrator turned the list
  -- on or narrowed it, a passkey it would refuse that was working until then keeps working until this time (UTC ISO),
  -- unless its model is reported compromised or revoked. NULL: no grace (accepted, or refused already).
  allowlist_grace_until TEXT
);
CREATE TABLE authenticator_metadata (
  id TEXT PRIMARY KEY,                 -- the AAGUID, or 'u2f:' and the first key identifier
  aaguid TEXT,
  key_ids TEXT NOT NULL DEFAULT '[]',  -- JSON array of hex SHA-1 key identifiers (fido-u2f)
  description TEXT NOT NULL DEFAULT '',
  root_certificates TEXT NOT NULL,     -- JSON array of base64 DER certificates
  status_reports TEXT NOT NULL,        -- JSON array of { status, effectiveDate }
  attestation_types TEXT NOT NULL DEFAULT '[]',
  mds_no INTEGER NOT NULL
);
CREATE TABLE webauthn_challenges (
  id TEXT PRIMARY KEY,                 -- hex SHA-256 of the challenge bytes
  purpose TEXT NOT NULL,
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT,
  statement TEXT,
  ip TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at TEXT NOT NULL,
  used_at TEXT
);
CREATE TABLE signature_evidence (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  passkey_id TEXT,
  purpose TEXT NOT NULL,
  record_type TEXT NOT NULL,
  record_ids TEXT NOT NULL,
  statement_hash TEXT NOT NULL,
  evidence_enc TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "signature_evidence"("id","user_id","passkey_id","purpose","record_type","record_ids","statement_hash","evidence_enc","created_at") VALUES('7a9dc24c-3bc2-4354-9851-a8b8ae782fca','b20d0b83-219a-4e3f-80da-20d104e6550c','fixture-signature_evidence-0','fixture-signature_evidence-0','fixture-signature_evidence-0','fixture-signature_evidence-0','fixture-signature_evidence-0','v1:ZfihGcAATlyRmYXQ:Pa0xFhWrt6FlbJj3i22DhA==:wyShueEbPgf+R90xqO1R9hqXYcy+LCOuwRrP42O/C1hIA+YnIBnVT7xgOFYOahth+g0nSw==','2026-10-01T04:54:16.290Z');
INSERT INTO "signature_evidence"("id","user_id","passkey_id","purpose","record_type","record_ids","statement_hash","evidence_enc","created_at") VALUES('ee979469-c203-49b8-8316-d4c0382a33b8','abe287a1-4688-46fc-a02f-26dfc06086d0','fixture-signature_evidence-1','fixture-signature_evidence-1','fixture-signature_evidence-1','fixture-signature_evidence-1','fixture-signature_evidence-1','v1:YrQ4GV4QSYXUdXf3:mJe6AmxmPlLNedDkbPNqTQ==:e1iRxpqCnYJ0jv5kMKb8P0pKyfjq5Z/3CA==','2026-10-01T04:54:16.292Z');
INSERT INTO "signature_evidence"("id","user_id","passkey_id","purpose","record_type","record_ids","statement_hash","evidence_enc","created_at") VALUES('620985e1-d647-498c-8344-0b9cda70ec74','5bb9a771-70ec-4572-b54a-c67774a99537',NULL,'fixture-signature_evidence-2','fixture-signature_evidence-2','fixture-signature_evidence-2','fixture-signature_evidence-2','v1:Sn0mjIOXjj4HN4x6:zeJApekQPRpnz78+jIYeoA==:cAQ2XLyDNIxbFLlIFd4DBOKCMAgvUh8v83DU','2026-10-01T04:54:16.293Z');
CREATE TABLE api_keys (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  key_hash TEXT NOT NULL UNIQUE,
  prefix TEXT NOT NULL,
  scopes TEXT NOT NULL DEFAULT 'intake',
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_used_at TEXT,
  revoked_at TEXT
);
CREATE TABLE clients (
  id TEXT PRIMARY KEY,
  client_code TEXT NOT NULL UNIQUE,    -- non-PHI identifier for reports / de-identified views
  first_name_enc TEXT NOT NULL,
  last_name_enc TEXT NOT NULL,
  last_name_idx TEXT,
  full_name_idx TEXT,
  -- Coarse blind indexes that make search tolerant of typos and partial names without storing any name in
  -- the clear: the first three letters of the surname, and its Soundex code, each HMAC'd with the index
  -- key. They are lower entropy than the exact indexes, but anyone holding the index key can already test
  -- a specific name against those, and both live in the same database as the ciphertext.
  name_prefix_idx TEXT,
  name_phonetic_idx TEXT,
  first_name_idx TEXT,
  first_name_prefix_idx TEXT,
  preferred_name_enc TEXT,
  preferred_name_idx TEXT,             -- blind index of the preferred name / alias, so "Jay" finds Jamie
  dob_enc TEXT,
  dob_idx TEXT,
  phone_enc TEXT,
  phone_idx TEXT,
  alt_phone_enc TEXT,
  email_enc TEXT,
  address_enc TEXT,
  city TEXT,
  zip TEXT,
  gender TEXT,
  pronouns TEXT,
  race_ethnicity TEXT,
  race_codes TEXT,                     -- comma separated CalOMS/OMB race codes (reportable; race_ethnicity stays for free text)
  preferred_language TEXT DEFAULT 'English',
  veteran INTEGER DEFAULT 0,
  housing_status TEXT,
  insurance TEXT,
  medicaid_id_enc TEXT,
  emergency_contact_enc TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('waitlist','active','inactive','closed','deceased')),
  intake_date TEXT,
  discharge_date TEXT,
  discharge_reason TEXT,
  referral_source TEXT,
  referral_date TEXT,                  -- when this person was referred in, distinct from intake_date (when services actually started)
  engagement_date TEXT,                -- when they first actually engaged with services; time-to-engagement = engagement_date - referral_date
  primary_substance TEXT,
  secondary_substances TEXT,
  route_of_use TEXT,
  asam_level TEXT,
  mat_status TEXT,                     -- none, interested, referred, active, discontinued
  mat_medication TEXT,
  overdose_history INTEGER DEFAULT 0,
  last_overdose_date TEXT,
  naloxone_provided INTEGER DEFAULT 0,
  naloxone_last_date TEXT,
  risk_level TEXT DEFAULT 'moderate',
  justice_involved INTEGER DEFAULT 0,
  pregnant_or_parenting INTEGER DEFAULT 0,
  co_occurring_mh INTEGER DEFAULT 0,
  goals_enc TEXT,
  flags_enc TEXT,                      -- comma separated safety flags, encrypted
  contact_preferences_enc TEXT,             -- "safe contact" notes (who must not be told, when to call): encrypted
  ok_to_text INTEGER DEFAULT 0,
  ok_to_voicemail INTEGER DEFAULT 0,
  created_by TEXT REFERENCES users(id),
  -- Set when this record was merged into another as a duplicate; the row is kept so old references and the
  -- audit trail still resolve, but it no longer appears anywhere staff work.
  merged_into TEXT REFERENCES clients(id),
  -- A legal hold (litigation, investigation, a patient's own request) exempts the record from the retention
  -- purge in server/retention.js and from deletion until an administrator clears it.
  legal_hold INTEGER NOT NULL DEFAULT 0,
  -- Free-text reasons can name the person or their situation, so they are encrypted here and the audit entry
  -- records only that one was given: why the hold was placed, why it was last cleared, and why the record
  -- was deleted or merged away.
  legal_hold_reason_enc TEXT,
  legal_hold_cleared_reason_enc TEXT,
  removed_reason_enc TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at TEXT,
  -- A client known by a syringe services participant code instead of a name (1.21.0, migration 62; the programme
  -- setting participant_code_default): encrypted like the visit's code (server/participant-code.js), and counted
  -- and found by its blind index in the same domain, so a code on an anonymous visit and on a client match.
  -- A coded client's first_name_enc and last_name_enc hold an empty string until someone adds a name.
  participant_code_enc TEXT,
  participant_code_idx TEXT
);
