CREATE TABLE interventions (
  id TEXT PRIMARY KEY,
  -- nullable: community naloxone distribution and street outreach are real services with no identified client
  client_id TEXT REFERENCES clients(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id),
  type TEXT NOT NULL,
  occurred_at TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL DEFAULT 0,
  location TEXT DEFAULT 'office',
  modality TEXT DEFAULT 'in_person',
  outcome TEXT,
  stage_of_change TEXT,
  naloxone_kits INTEGER DEFAULT 0,
  fentanyl_strips INTEGER DEFAULT 0,
  funding_source_id TEXT REFERENCES funding_sources(id),
  -- Which allocation the cost below actually draws down. Nullable: a worker can log a direct cost against
  -- just the fund with no specific line, the same as expenditures.budget_line_id already allows.
  budget_line_id TEXT REFERENCES budget_lines(id) ON DELETE SET NULL,
  cost REAL DEFAULT 0,
  summary_enc TEXT,
  follow_up_due TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  -- Syringe services (migration 44, docs/SUPPLIES.md). The supply site the visit's supplies came from
  -- (supply_sites; no REFERENCES, so a visit never fails to sync over a site), and the used syringes and
  -- sharps brought back: a count, or an estimate from the container's volume (returns_estimated=1,
  -- sharps_returned_litres), which is how CDPH syringe services reporting counts returns it did not count.
  supply_site_id TEXT,
  syringes_returned INTEGER NOT NULL DEFAULT 0,
  returns_estimated INTEGER NOT NULL DEFAULT 0,
  sharps_returned_litres REAL,
  -- Anonymous syringe services participant code (migration 51, docs/SUPPLIES.md): on a contact with no client
  -- record, the code the participant gives each time (built from details only they can reproduce), so the SSP
  -- summary can count unique participants without anyone being identified. It is built from personal details,
  -- so it is kept encrypted, and counted by its blind index (participant_code_idx, HMAC under the index key).
  participant_code_enc TEXT,
  participant_code_idx TEXT
