INSERT INTO "court_orders"("id","client_id","order_type","court_enc","case_ref_enc","issued_at","expires_at","recipient_enc","purpose_enc","scope_enc","findings_recorded","notice_requirement_met","covers_counseling_notes","document_ref_enc","status","vacated_at","vacated_reason_enc","recorded_by","created_at","updated_at") VALUES('31ad389b-3610-4062-b318-7877425cf139','5e925fc9-e13a-4c14-88cf-8a23ffb06559','program_investigation_2_66','v1:wm0DUjFaShlLmblE:zuOqr3hvpfBl/Jb+3UkWVA==:KQETwE5XkckozUKZcGK64b7HVOkTiYavO3nZypcVRQalaHOwid+doJ9r93j0CJGRNjLyyxFqWZWGglqT',NULL,'2026-08-12T10:00:00.000Z',NULL,NULL,'v1:ldil1Reahexxk+54:dDTvWX6v59gGrVxLVicUeg==:m1jA/K2oZaMa4fVgyzOZWxUNunyPYZoadg==','v1:LOU7jMsE/+hn6RoD:ZDopuZyEhC6mWTpcmkOn9Q==:Vtg0qq50UMHfsBJcXe/xOlEr0grMkogHcZ2e4P666Vx80jTCn+EcvFXPDc8=',0,0,0,NULL,'active',NULL,NULL,'b20d0b83-219a-4e3f-80da-20d104e6550c','2026-10-01T04:54:16.230Z','2026-10-01T04:54:16.230Z');
CREATE TABLE disclosures (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  consent_id TEXT REFERENCES consents(id) ON DELETE SET NULL,
  recipient_enc TEXT NOT NULL,
  purpose_enc TEXT NOT NULL,
  what_enc TEXT NOT NULL,
  method TEXT,
  disclosed_at TEXT NOT NULL,
  disclosed_by TEXT NOT NULL REFERENCES users(id),
  basis TEXT,                          -- consent, court_order, medical_emergency, qsoa, audit, research, export
  -- Why a disclosure was made without consent (required for 'other' and 'medical_emergency'); PHI, encrypted.
  justification_enc TEXT,
  source TEXT,                         -- referral, export, manual: what caused the disclosure to be recorded
  source_ref TEXT,
  -- Migration 29: the subpart E order relied on, whether the information is for use in a proceeding
  -- against the patient (§2.12(d)), whether it includes SUD counseling notes (§2.31(b)), and which
  -- wording of the §2.32 notice went with it.
  court_order_id TEXT REFERENCES court_orders(id) ON DELETE SET NULL,
  legal_proceeding INTEGER NOT NULL DEFAULT 0,
  counseling_notes INTEGER NOT NULL DEFAULT 0,
  notice_version TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
