CREATE TABLE caloms_records (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  episode_id TEXT NOT NULL REFERENCES episodes(id) ON DELETE CASCADE,
  record_type TEXT NOT NULL CHECK (record_type IN ('admission','discharge','annual_update')),
  provider_id TEXT,                    -- the CalOMS provider ID (Settings -> State reporting) the record is reported under
  record_date TEXT NOT NULL,           -- admission date, discharge date, or the annual update's date
  service_type TEXT,                   -- admission only: CalOMS type of service code
  discharge_status TEXT,               -- discharge only: CalOMS discharge status code
  answers_enc TEXT,                    -- encrypted JSON of the coded answers
  extracted_at TEXT,
  created_by TEXT REFERENCES users(id),
  updated_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO "caloms_records"("id","client_id","episode_id","record_type","provider_id","record_date","service_type","discharge_status","answers_enc","extracted_at","created_by","updated_by","created_at","updated_at") VALUES('454d10b0-e76a-4379-ad2b-58bc6ec5c96c','a72156a8-a8e7-44d6-855d-734f2eae5404','8fc41a20-0658-4f16-b1c5-dcc833d523f1','admission',NULL,'2026-05-04','01',NULL,'v1:5KbdQSxV9AiNSw7K:I13XrHA82u7CWhCfmJOYrQ==:',NULL,'5bb9a771-70ec-4572-b54a-c67774a99537','5bb9a771-70ec-4572-b54a-c67774a99537','2026-10-01T04:54:15.804Z','2026-10-01T04:54:15.804Z');
