CREATE TABLE county_programmes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  keep_files INTEGER NOT NULL DEFAULT 0,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by TEXT REFERENCES users(id),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  on_suds INTEGER NOT NULL DEFAULT 1
);
INSERT INTO "county_programmes"("id","name","active","keep_files","notes","created_at","created_by","updated_at","on_suds") VALUES('1df40256-8d8f-4261-a418-5bf563628329','Fixture Programme',1,0,NULL,'2026-10-01T04:54:15.844Z','3c33f58c-aa72-48ef-b4b7-0cfa790798e0','2026-10-01T04:54:15.844Z',1);
INSERT INTO "county_programmes"("id","name","active","keep_files","notes","created_at","created_by","updated_at","on_suds") VALUES('c159aa6f-4978-4c13-a044-e354af5885ed','Paper Reports Collective',1,0,NULL,'2026-10-01T04:54:15.953Z','3c33f58c-aa72-48ef-b4b7-0cfa790798e0','2026-10-01T04:54:15.953Z',0);
CREATE TABLE county_programme_keys (
  id TEXT PRIMARY KEY,
  programme_id TEXT NOT NULL REFERENCES county_programmes(id),
  public_key TEXT NOT NULL,
  fingerprint TEXT NOT NULL UNIQUE,
  added_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  added_by TEXT REFERENCES users(id),
  replaced_at TEXT,
  replaced_by TEXT REFERENCES users(id),
  compromised_at TEXT,                 -- set: the files it signed stop counting
  compromised_by TEXT REFERENCES users(id)
);
INSERT INTO "county_programme_keys"("id","programme_id","public_key","fingerprint","added_at","added_by","replaced_at","replaced_by","compromised_at","compromised_by") VALUES('3a236a99-a9ef-4cc0-8883-3d25897ad981','1df40256-8d8f-4261-a418-5bf563628329','-----BEGIN PUBLIC KEY-----
