INSERT INTO "county_submissions"("id","programme_id","key_id","period_from","period_to","schema_version","programme_name","generated_at","suds_version","payload_enc","sha256","signature","received_at","received_by","superseded_by","withdrawn_at","withdrawn_by","source","entered_via","source_ref_enc") VALUES('41bcd72d-d139-4ffa-ae21-3970d8b45945','1df40256-8d8f-4261-a418-5bf563628329','3a236a99-a9ef-4cc0-8883-3d25897ad981','2026-04-01','2026-06-30',1,'County Harm Reduction and Outreach Program','2026-10-01T04:54:15.923Z','1.22.0','v1:xs90wr5OxVSCQ5pH:Oij48zToxh/NuE0AxnfMew==:','57ba0020b8d4516d95f5d3b383700f7b9f1b19b1dae90ca9120cd7b03e8d75de','1cP7LKdUEsXqe9Gcm8AN+3f4pYuJaGR0pbr+ZrmXVr+pJeGx+doGZ8eamFAU2ISWP2TP2wxyU+ajBJGzYLr0AQ==','2026-10-01T04:54:15.948Z','3c33f58c-aa72-48ef-b4b7-0cfa790798e0',NULL,NULL,NULL,'signed',NULL,NULL);
INSERT INTO "county_submissions"("id","programme_id","key_id","period_from","period_to","schema_version","programme_name","generated_at","suds_version","payload_enc","sha256","signature","received_at","received_by","superseded_by","withdrawn_at","withdrawn_by","source","entered_via","source_ref_enc") VALUES('425a4476-3832-41da-95aa-e1b17dcd0200','c159aa6f-4978-4c13-a044-e354af5885ed',NULL,'2026-01-01','2026-03-31',2,'Paper Reports Collective','2026-10-01T04:54:15.958Z','1.22.0','v1:vNghTO9UzG20JCta:DgTS8Rf+JIJPp+VMvt6Xtg==:','28cb70ebe00c62b4b71aebb5ae209527817cdb8452e68bbb276adcbea7dbaa21',NULL,'2026-10-01T04:54:15.959Z','3c33f58c-aa72-48ef-b4b7-0cfa790798e0',NULL,NULL,NULL,'county_entered','form','v1:erUTlpe1wXkPcyUS:96WyS7L1Ijg3JJrXOb1m/Q==:Spn5btQDCzEQpEpDX5vFh7dpdKDRPvmzs8ojYA54nibrodTI8CEyhF6NQfBw');
CREATE TABLE county_publications (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('release','withdrawal')),
  release_id TEXT REFERENCES county_publications(id),
  period_from TEXT NOT NULL,
  period_to TEXT NOT NULL,
  threshold INTEGER NOT NULL,
  entered TEXT NOT NULL CHECK (entered IN ('include','exclude')),
  method TEXT NOT NULL,                -- JSON: the method and its parameters
  content TEXT,                        -- a release: the canonical JSON of what was published
  sha256 TEXT NOT NULL,                -- of the release's content (a withdrawal: of the release it withdraws)
  reason_enc TEXT,                     -- a withdrawal: why, AES-256-GCM
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by TEXT REFERENCES users(id),
  CHECK ((kind = 'release' AND release_id IS NULL AND content IS NOT NULL AND reason_enc IS NULL) OR (kind = 'withdrawal' AND release_id IS NOT NULL AND content IS NULL))
);
INSERT INTO "county_publications"("id","kind","release_id","period_from","period_to","threshold","entered","method","content","sha256","reason_enc","created_at","created_by") VALUES('4c8eb36e-97f0-4f71-8171-09a23b793827','release',NULL,'2026-01-01','2026-03-31',11,'include','{"name":"SUDS small-cell method (server/sdc.js), county release audited against each program''s own release","threshold":11,"screened_measures":["reversals","people_served","referrals_made","people_linked","moud_linked","treatment_admissions","people_trained"],"exact":"money and the outcomes that are not counts of people","differencing":"audited against the county totals and every program''s own publication release (each program''s figure as its own release would show it at most)","entered":"include","suds_version":"1.22.0"}','{"county":{"code":"K33M-RPHB","name":"County Harm Reduction and Outreach Program"},"figures_entered_by_the_county":{"counted":true,"left_out":[],"programmes":["Paper Reports Collective"]},"format":"suds-county-publication","method":{"differencing":"audited against the county totals and every program''s own publication release (each program''s figure as its own release would show it at most)","entered":"include","exact":"money and the outcomes that are not counts of people","name":"SUDS small-cell method (server/sdc.js), county release audited against each program''s own release","screened_measures":["reversals","people_served","referrals_made","people_linked","moud_linked","treatment_admissions","people_trained"],"suds_version":"1.22.0","threshold":11},"notes":["Combined figures of the programs listed, for the whole period. A program''s submission counts when its whole period lies inside the period chosen here; nothing is pro-rated. Where two of one program''s submissions overlap (a quarter and a month inside it), the longer one counts, except that a signed file always counts over figures the county entered. A program whose submissions cover only part of the period is marked \"part of the period\". An inactive program''s files count only if the county chose to keep counting them.","Counts of people are each program''s own count, added up: a person served by two programs counts twice. They are not unduplicated.","Counts of people and of events are screened: a total from 1 to 10 is shown as \"<11\", and a total that could be subtracted with the programs'' own published figures to reveal a small one is \"suppressed\". Zero is shown as 0. Money, contacts, kits, test strips, syringes, education sessions and staff training hours are not counts of people and are exact.","Suppressed and withheld figures are listed with why, never with their values. Screened automatically by SUDS''s method; not an expert determination.","Figures of Paper Reports Collective were entered by the county — not signed by the program: typed or imported by the county''s staff from a document the program sent."],"period":{"from":"2026-01-01","to":"2026-03-31"},"programmes":[{"coverage":"whole","name":"Fixture Programme","source":"signed"},{"coverage":"whole","name":"Paper Reports Collective","source":"county_entered"}],"release_id":"8ec354c989a224fd","rows":[{"group":"spending","key":"spend_approved","label":"Spent from settlement funds (approved or reimbursed)","money":true,"section":"Spending","value":1000.5},{"group":"spending","key":"spend_pending","label":"Pending approval","money":true,"section":"Spending","value":25},{"group":"use","key":"core_h","label":"H. Expanding syringe service programs (Exhibit E, Schedule A (Core Strategies))","money":true,"section":"Spent by allowable use (Exhibit E)","value":1000.5},{"group":"hiaa","key":"hiaa_4","label":"4. Diversion of people with SUD from the justice system into treatment, including training and resources for first and early responders, and outreach, diversion, deflection and harm reduction","money":true,"section":"Spent by High Impact Abatement Activity","value":1000.5},{"group":"outcome","key":"contacts","label":"Contacts (visits and outreach contacts)","money":false,"section":"Outcomes","value":120},{"group":"outcome","key":"naloxone_kits","label":"Naloxone kits distributed","money":false,"section":"Outcomes","value":80},{"group":"outcome","key":"reversals","label":"Overdose reversals reported (naloxone used, the person survived)","money":false,"screened":true,"section":"Outcomes","suppressed":"small","value":"<11"},{"group":"outcome","key":"fentanyl_strips","label":"Fentanyl test strips distributed","money":false,"section":"Outcomes","value":300},{"group":"outcome","key":"syringes","label":"Syringes distributed","money":false,"section":"Outcomes","value":900},{"group":"outcome","key":"people_served","label":"People served (each program''s own count, summed)","money":false,"screened":true,"section":"Outcomes","value":70},{"group":"outcome","key":"referrals_made","label":"Referrals made for the people served (each program''s own count, summed)","money":false,"screened":true,"section":"Outcomes","value":14},{"group":"outcome","key":"people_linked","label":"People linked to care: a referral admitted or completed (each program''s own count, summed)","money":false,"screened":true,"section":"Outcomes","suppressed":"small","value":"<11"},{"group":"outcome","key":"moud_linked","label":"People linked to medication for OUD (each program''s own count, summed)","money":false,"screened":true,"section":"Outcomes","suppressed":"small","value":"<11"},{"group":"outcome","key":"treatment_admissions","label":"Treatment admissions (episodes of care opened)","money":false,"screened":true,"section":"Outcomes","suppressed":"small","value":"<11"},{"group":"outcome","key":"education_contacts","label":"Education and training sessions (visits recorded as Education)","money":false,"section":"Outcomes","value":5},{"group":"outcome","key":"people_trained","label":"People trained in education sessions (each program''s own count, summed)","money":false,"screened":true,"section":"Outcomes","suppressed":"small","value":"<11"},{"group":"outcome","key":"staff_training_hours","label":"Staff training hours (approved time recorded as Training)","money":false,"section":"Outcomes","value":12.5}],"schema_version":1,"suppressed":[{"key":"reversals","label":"Overdose reversals reported (naloxone used, the person survived)","reason":"small","shown":"<11","why":"Shown as \"<11\": the county total is from 1 to 10."},{"key":"people_linked","label":"People linked to care: a referral admitted or completed (each program''s own count, summed)","reason":"small","shown":"<11","why":"Shown as \"<11\": the county total is from 1 to 10."},{"key":"moud_linked","label":"People linked to medication for OUD (each program''s own count, summed)","reason":"small","shown":"<11","why":"Shown as \"<11\": the county total is from 1 to 10."},{"key":"treatment_admissions","label":"Treatment admissions (episodes of care opened)","reason":"small","shown":"<11","why":"Shown as \"<11\": the county total is from 1 to 10."},{"key":"people_trained","label":"People trained in education sessions (each program''s own count, summed)","reason":"small","shown":"<11","why":"Shown as \"<11\": the county total is from 1 to 10."}],"withheld":[]}','70aeca94caeecfe67c9a6e754349537653feda28698814cc17f824051aaeadf1',NULL,'2026-10-01T04:54:16.084Z','3c33f58c-aa72-48ef-b4b7-0cfa790798e0');
