CREATE TRIGGER county_publications_no_update BEFORE UPDATE OF id, kind, release_id, period_from, period_to, threshold, entered, method, content, sha256, created_at, created_by ON county_publications
  BEGIN SELECT RAISE(ABORT, 'county_publications is append-only: a published release is never changed (withdraw it: a new row)'); END;
CREATE TRIGGER county_publications_no_delete BEFORE DELETE ON county_publications
  BEGIN SELECT RAISE(ABORT, 'county_publications is append-only: a published release is never deleted'); END;
